def fetch_shpp_main_items(item_ids, bo_cookies=DEFAULT_BO_COOKIES, timeout=10):
    """BO 배송정보관리 API(listItemShippForPaging.ssg)를 호출하여 SSG상품번호별 배송주체(shppMainCd) 맵핑을 반환"""
    if not item_ids:
        return {}
    
    unique_ids = list(dict.fromkeys(item_ids))
    mapping = {}

    chunk_size = 50
    for i in range(0, len(unique_ids), chunk_size):
        chunk = unique_ids[i:i + chunk_size]
        items_str = ",".join(chunk)

        params = {
            'formVersion': '20170725',
            'searchDtType': '1',
            'search_start_dt_disp': '2025-01-01',
            'searchStartDt': '20250101',
            'search_end_dt_disp': '2026-12-31',
            'searchEndDt': '20261231',
            'set_date': '3',
            'search_item_id_txt': items_str,
            'searchItemIds': items_str,
            'searchItemRegDivCd': '',
            'searchItemRegDtlCd': '',
            'searchShppMainCd': '',
            'page': '1',
            'pageSize': '100'
        }

        query_str = urllib.parse.urlencode(params)
        url = f"{API_BO_ITEM_SHIPP}?{query_str}"
        req = urllib.request.Request(url)
        req.add_header('Cookie', bo_cookies)
        req.add_header('accept', 'application/xml, text/xml, */*; q=0.01')
        req.add_header('is_dhx_griddata_req', 'true')
        req.add_header('x-requested-with', 'XMLHttpRequest')
        req.add_header('User-Agent', 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)')

        try:
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                xml_data = resp.read()
                root = ET.fromstring(xml_data)

                item_id_idx = None
                shpp_main_idx = None
                head = root.find('head')
                if head is not None:
                    columns = head.findall('column')
                    for c_idx, col in enumerate(columns):
                        col_id = col.attrib.get('id', '').lower()
                        col_text = (col.text or '').strip()
                        if 'itemid' in col_id or '상품번호' in col_text:
                            item_id_idx = c_idx
                        elif 'shppmain' in col_id or '배송주체' in col_text:
                            shpp_main_idx = c_idx

                for row in root.findall('.//row'):
                    row_id = row.attrib.get('id', '')
                    cells = [c.text or '' for c in row.findall('cell')]
                    if not cells:
                        continue

                    curr_item_id = ''
                    if item_id_idx is not None and item_id_idx < len(cells):
                        curr_item_id = cells[item_id_idx].strip()
                    elif row_id and any(row_id == uid for uid in chunk):
                        curr_item_id = row_id
                    else:
                        for c_val in cells:
                            c_clean = c_val.strip()
                            if c_clean in chunk:
                                curr_item_id = c_clean
                                break

                    curr_shpp_main = ''
                    if shpp_main_idx is not None and shpp_main_idx < len(cells):
                        curr_shpp_main = cells[shpp_main_idx].strip()
                    else:
                        for c_val in cells:
                            c_clean = c_val.strip()
                            if c_clean in SHPP_MAIN_MAP:
                                curr_shpp_main = c_clean
                                break
                            for code, desc in SHPP_MAIN_MAP.items():
                                if code in c_clean or (len(c_clean) > 2 and c_clean in desc):
                                    curr_shpp_main = code
                                    break
                            if curr_shpp_main:
                                break

                    if curr_item_id:
                        disp_val = SHPP_MAIN_MAP.get(curr_shpp_main, curr_shpp_main) if curr_shpp_main else "-"
                        mapping[curr_item_id] = disp_val
        except Exception:
            pass

    return mapping

def get_shpp_main_display(channel_name, store_info="", ssg_no=""):
    """채널명 및 영업점/사이트번호/상품번호 기반 배송주체 자동 판별 (지능형 Fallback, 명칭만 반환)"""
    ch = channel_name or ""
    st = store_info or ""
    no = ssg_no or ""

    # 1. 점포택배 및 장보기 채널 -> 점포PP
    if "점포택배" in ch or "장보기" in ch:
        return "점포PP"

    # 2. 백화점 개별 등록 상품 배송주체 (센터입고 / 브랜드직배)
    if no in CENTER_BRAND_ITEMS:
        return "센터입고"
    if no in DIRECT_BRAND_ITEMS:
        return "브랜드직배"

    # 3. 백화점 점포 중 PP입고 운영 점포 (김해점 1017 등)
    if "김해점" in st or "1017" in st:
        return "PP입고"

    # 4. 신세계백화점 일반 점포 매장 출고 -> 매장집하
    if "신세계백화점" in ch or "백화점" in ch:
        return "매장집하"

    # 5. 프리미엄아울렛 -> 협력업체
    if "아울렛" in ch:
        return "협력업체"

    # 6. 신세계몰 (직매입: 센터입고 / 온라인: 협력업체)
    if "신세계몰" in ch:
        if "직매입" in ch:
            return "센터입고"
        return "협력업체"

    # 7. 직매입 / 새벽배송 등 센터 출고 -> 센터입고
    if "직매입" in ch or "새벽배송" in ch:
        return "센터입고"

    # 8. 이마트몰 점포/사이트
    if "이마트몰" in ch:
        if "2551" in st or "NE.O" in st:
            return "센터입고"
        return "점포PP"

    # 9. 영업점/사이트번호 기준 보조 판별
    if "점(" in st or any(f"10{i:02d}" in st for i in range(1, 35)):
        return "매장집하"
    if "6004" in st or "7008" in st:
        return "협력업체"
    if "2551" in st:
        return "센터입고"

    return "매장집하"

